import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { generateIdentity, identityToRecipient } from 'age-encryption';
import { decryptDiff } from './decrypt.js';

// Synthetic ciphertext and envelope generated by Rust's engine and envelope modules.
const fixture=JSON.parse(await readFile(new URL('../../tests/signed-browser-fixture.json',import.meta.url),'utf8'));
const decrypt=(text=fixture.text,identity=fixture.identity,repo='acme/repo',group='team',recipient=fixture.recipient)=>
  decryptDiff(text,identity,fixture.envelope,'.env','env',repo,group,recipient);

test('browser derives the Rust signer and decrypts a Rust envelope and value',async()=>{
 assert.equal(await decrypt(), 'TOKEN=synthetic\n');
 assert.equal(await decrypt('+'+fixture.text), '+TOKEN=synthetic\n');
 await assert.rejects(()=>decrypt(fixture.text,undefined,'other/repo'),/context/);
 await assert.rejects(()=>decrypt(fixture.text,undefined,undefined,''),/required/);
 const unrelated=await generateIdentity();
 await assert.rejects(()=>decrypt(fixture.text,unrelated));
 await assert.rejects(async()=>decrypt(fixture.text,undefined,undefined,undefined,await identityToRecipient(unrelated)),/context/);
});

test('browser rejects a wrong signer, changed signature, and mixed unsigned assignments',async()=>{
 await assert.rejects(()=>decrypt(fixture.wrongSignerText),/signer/);
 const tampered=fixture.text.replace(/ENC\[v2:([^\]]+)\]/,(match:string,body:string)=>{
  const bytes=Buffer.from(body,'base64');
  bytes[40]^=1;
  return match.replace(body,bytes.toString('base64'));
 });
 await assert.rejects(()=>decrypt(tampered),/signature/);
 await assert.rejects(()=>decrypt(fixture.text+'OTHER=unsigned\n'),/unsigned/);
});
